#!/usr/bin/env bun

/**
 * Project-owned extension installer for Shibumi projects.
 *
 *   bun run shibumi list                 what is installed and available
 *   bun run shibumi add <name>           preview, confirm, install
 *   bun run shibumi add <name> --dry-run preview only, write nothing
 *   bun run shibumi remove <name>        delete installed code, reverse edits
 *
 * Extension bundles are embedded below, generated from the create-shibumi
 * repository and checksum-verified at scaffold time; installation touches no
 * network. Every write and edit is listed before anything happens. Hooks
 * match exact unique source text and stop on changed text instead of
 * guessing. Removal deletes code and reverses edits; it never drops tables.
 *
 * Flags: --yes (skip confirmation), --force (remove only: also delete files
 * modified after install and skip edits that no longer match), --dry-run
 * (preview only). Conflicting files always stop an install; move them aside
 * and re-run.
 */

import { existsSync, lstatSync, mkdirSync, readFileSync, readdirSync, rmSync, rmdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve, sep } from "node:path";

export interface ExtensionHook {
  file: string;
  find: string;
  insert?: string;
  replace?: string;
}

export interface ExtensionFile {
  to: string;
  content: string;
}

export interface ExtensionBundle {
  name: string;
  title: string;
  description: string;
  version: string;
  requires: "database" | null;
  // Other extensions that must already be installed (e.g. uploads needs auth).
  dependsOn?: string[];
  env: string[];
  deps?: Record<string, string>;
  files: ExtensionFile[];
  hooks: ExtensionHook[];
  migration: string | null;
  agentsFile: string;
  rootSection: string;
  removeNote?: string;
}

